@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Sharp Light — exact styles from the original site (browser-extracted 2026) */
  /* Background: rgb(247,247,247) = near-white  */
  /* Foreground: rgb(46,46,46) = charcoal body text */
  /* Primary button: charcoal bg (#2e2e2e) + precision layered shadow */
  /* Ring/focus: blue #335cff = oklch(0.5547 0.2451 266.71) */
  /* Card: white bg + multi-layer doubling-radii shadow + 1px ring */

  --background: oklch(0.9772 0 0);          /* rgb(247,247,247) near-white */
  --foreground: oklch(0.3008 0 0);          /* rgb(46,46,46) charcoal */

  --card: oklch(1 0 0);               /* white */
  --card-foreground: oklch(0.3008 0 0);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.3008 0 0);

  /* Primary: charcoal near-black (CTA button bg matches body text color) */
  --primary: oklch(0.3008 0 0);
  --primary-foreground: oklch(1 0 0);

  /* Secondary: white surface button */
  --secondary: oklch(1 0 0);
  --secondary-foreground: oklch(0.3008 0 0);

  --muted: oklch(0.9696 0 0);
  --muted-foreground: oklch(0.4741 0 0);    /* rgb(92,92,92) */

  --accent: oklch(0.9619 0 0);
  --accent-foreground: oklch(0.3008 0 0);

  --destructive: oklch(0.6356 0.2082 25.38);
  --destructive-foreground: oklch(1 0 0);

  --border: oklch(0.9389 0 0);              /* rgb(235,235,235) */
  --input: oklch(0.9772 0 0);               /* same as bg */
  --ring: oklch(0.5547 0.2451 266.71);            /* blue #335cff — focus rings */

  /* 10px radius — Sharp Light's signature rounded-[10px] */
  --radius: 0.625rem;

  /* Shadow overrides — light theme needs subtle shadows, not dark-mode 40% black */
  --shadow-2xs: 0 1px 2px 0 rgba(0,0,0,0.04);
  --shadow-xs:  0 1px 2px 0 rgba(0,0,0,0.06);
  --shadow-sm:  0 1px 3px 0 rgba(0,0,0,0.08), 0 1px 2px -1px rgba(0,0,0,0.06);
  --shadow:     0 1px 3px 0 rgba(0,0,0,0.1),  0 1px 2px -1px rgba(0,0,0,0.08);
  --shadow-md:  0 4px 6px -1px rgba(0,0,0,0.08), 0 2px 4px -2px rgba(0,0,0,0.06);
  --shadow-lg:  0 8px 16px -2px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.06), 0 0 0 1px rgba(0,0,0,0.04);
  --shadow-xl:  0 16px 24px -4px rgba(0,0,0,0.12), 0 8px 10px -6px rgba(0,0,0,0.08), 0 0 0 1px rgba(0,0,0,0.04);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-inter-var), var(--font-inter), "Inter", ui-sans-serif, system-ui, -apple-system,
      BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
